    "at_kpi_lift": { zh: "配置带来的 R² 增量", en: "R² lift from configuration" },
    "at_boundary_title": { zh: "分析范围与解释", en: "Scope and interpretation" },
    "at_boundary_lead": { zh: "年度截面分析按车系留出验证，评估产品属性对跨车系销量差异的解释力。", en: "The annual cross-sectional analysis holds out series to evaluate how product attributes explain sales differences across series." },
    "at_boundary_between": { zh: "适合比较车系之间的差异", en: "Designed for between-series differences" },
    "at_boundary_between_note": { zh: "评价对象为已有年度样本中留出的车系；未来年份预测需另行检验。", en: "Evaluation covers held-out series in the observed annual sample. Future-year forecasts require a separate evaluation." },
    "at_boundary_assoc": { zh: "配置与市场定位共同变化", en: "Specifications and market positioning co-vary" },
    "at_boundary_assoc_note": { zh: "配置与价格、品牌定位及目标人群存在共同变动；特征重要性描述模型依赖，不构成单项配置的因果效应。", en: "Specifications co-vary with price, brand positioning, and target buyers. Feature importance describes model reliance, not the causal effect of an individual specification." },
